import StatsSectionV4 from "./components/stats-section-v4"

export default function Page() {
  return <StatsSectionV4 />
}

"use client"

import * as React from "react"
import { Bar, ComposedChart, Line, XAxis, YAxis } from "recharts"

import { type ChartConfig, ChartContainer } from "@/components/ui/chart"
import { cn } from "@/lib/utils"

import { CHART_COLOR, weeklyInstalls } from "../lib/config"

const chartConfig = {
  installs: { label: "Installs", color: CHART_COLOR },
} satisfies ChartConfig

const peak = Math.max(...weeklyInstalls.map((point) => point.installs))

export function ScaleChart({ className }: { className?: string }) {
  const gradientId = `ssv4-bars-${React.useId().replace(/:/g, "")}`

  return (
    <ChartContainer
      config={chartConfig}
      className={cn("aspect-auto h-full w-full", className)}
    >
      <ComposedChart
        data={weeklyInstalls}
        margin={{ left: 0, right: 0, top: 32, bottom: 0 }}
        barCategoryGap={0}
      >
        <defs>
          <linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1">
            <stop
              offset="0%"
              stopColor="var(--color-installs)"
              stopOpacity={0.35}
            />
            <stop
              offset="100%"
              stopColor="var(--color-installs)"
              stopOpacity={0.03}
            />
          </linearGradient>
        </defs>
        <XAxis dataKey="week" hide />
        <YAxis hide domain={[0, peak]} />
        <Bar
          dataKey="installs"
          fill={`url(#${gradientId})`}
          barSize={1}
          isAnimationActive={false}
        />
        <Line
          dataKey="installs"
          type="monotone"
          stroke="var(--color-installs)"
          strokeWidth={2}
          dot={false}
          isAnimationActive={false}
        />
      </ComposedChart>
    </ChartContainer>
  )
}

/** Same neutral gray as the Next.js series in stats-section-v2. */
export const CHART_COLOR = "#888888"

export const sectionHeader = {
  title: "Adoption that compounds.",
  subtitle: "Every block installed makes the next project faster to ship.",
} as const

export type Stat = {
  id: string
  value: string
  label: string
}

export const stats: Stat[] = [
  { id: "installs", value: "1.2M", label: "installs this week" },
  { id: "projects", value: "48k", label: "projects shipped" },
  { id: "blocks", value: "310", label: "blocks and templates" },
  { id: "countries", value: "140+", label: "countries building" },
]

export type WeekPoint = {
  week: number
  installs: number
}

const WEEKS = 180
const FINAL_INSTALLS = 1200
const START_INSTALLS = 18
/** Higher values keep the curve flat for longer before it bends upward. */
const GROWTH = 4.2

/**
 * Weekly installs, in thousands: flat at first, then compounding up to the
 * 1.2M "installs this week" stat in the final week.
 */
export const weeklyInstalls: WeekPoint[] = Array.from(
  { length: WEEKS },
  (_, index) => {
    const t = index / (WEEKS - 1)
    const curve = (Math.exp(GROWTH * t) - 1) / (Math.exp(GROWTH) - 1)
    return {
      week: index + 1,
      installs: Math.round(
        START_INSTALLS + (FINAL_INSTALLS - START_INSTALLS) * curve
      ),
    }
  }
)
